{
  "name": "tenants.remove-user-from-tenant",
  "kind": "write",
  "description": "Remove a user\u0027s membership from an active tenant, revoking the user\u0027s role in that tenant. Allowed for a global administrator or a TenantOwner of the tenant; removing a user who is not a member is rejected. Removing the last TenantOwner is allowed; afterwards only a global administrator can manage the tenant\u0027s members, roles and configuration.",
  "schema": {
    "type": "object",
    "properties": {
      "TenantId": {
        "type": "string",
        "description": "Identifier of the tenant to remove the user from."
      },
      "UserId": {
        "type": "string",
        "description": "Identifier of the member to remove: the subject (sub) claim the identity provider issues for that user."
      }
    },
    "required": [
      "TenantId",
      "UserId"
    ],
    "additionalProperties": false
  },
  "example": {
    "TenantId": "acme",
    "UserId": "8d3f2a61-5b7e-4c0a-9e21-3f4b6c7d8e90"
  },
  "envelope": {
    "fixedTenant": "system",
    "aggregateIdRequired": false,
    "idempotencyKeyRequired": false,
    "arguments": [
      "aggregateId",
      "correlationId",
      "idempotencyKey",
      "extensions"
    ]
  },
  "lintFindings": [],
  "submittable": false,
  "reason": "configuration_invalid"
}
